const output = $input.first().json.stdout || '';
const lines = output.split('\n');
let nextStep = 'NONE';
for (let i = lines.length - 1; i >= 0; i--) {
  const match = lines[i].match(/\[NEXT_STEP\]:\s*(.*)/);
  if (match) {
    nextStep = match[1].trim();
    break;
  }
}
return { json: { stdout: output, NEXT_STEP: nextStep } };

const nextStepData = $node["Extract NEXT_STEP"].json;
const issueStatus = $node["Get Issue Status"].json.stdout?.trim();

let finalNextStep = nextStepData.NEXT_STEP;
if (issueStatus === 'CLOSED') {
  finalNextStep = 'NONE';
}

return { json: { ...nextStepData, NEXT_STEP: finalNextStep, issue_status: issueStatus } };

